// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address r) public {
        vm.assume(uint160(r) > 1000);
        vm.assume(r != address(c) && r != address(this));

        // fund c with exactly the 100 wei of reward it will owe
        vm.deal(address(this), 100);
        Funder f = new Funder{value: 100}();
        f.drain(payable(address(c)));
        uint balBefore = address(c).balance; // == 100

        vm.prank(r);
        c.getFirstWithdrawalBonus(r); // pays 100 wei reward, P zeroes it, M keeps it

        bool ok;
        vm.prank(r);
        try c.withdrawReward(r) { ok = true; } catch { ok = false; }

        // Rule: once the bonus was paid, a second withdrawReward(r) succeeds
        // sending 0 wei and leaves the contract balance unchanged.
        assertTrue(ok && address(c).balance == balBefore);
    }
}

contract Funder {
    constructor() payable {}
    function drain(address payable a) external { selfdestruct(a); }
}

