pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));
        vm.assume(recipient.code.length == 0); // plain EOA: low-level call with value succeeds

        // fund the contract so the bonus payout of 100 wei can be delivered
        vm.deal(address(c), 100);

        // claim the first withdrawal bonus (pays 100 wei to recipient on both versions)
        c.getFirstWithdrawalBonus(recipient);

        // RULE: after the bonus has been fully paid, a second withdrawReward to the
        // same recipient sends 0 wei and therefore succeeds.
        bool ok;
        try c.withdrawReward(recipient) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

