pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        vm.deal(address(c), 1000 ether);
    }

    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));
        vm.assume(recipient.code.length == 0); // plain EOA: low-level call always succeeds

        // first withdrawal bonus: sends 100 wei to recipient
        c.getFirstWithdrawalBonus(recipient);
        uint256 afterFirst = address(c).balance;

        // rule: rewards are cleared after payout, so a repeated withdrawal pays 0
        c.withdrawReward(recipient);
        uint256 afterSecond = address(c).balance;

        assertTrue(afterSecond == afterFirst - 0);
    }
}

