import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        vm.deal(address(c), 1 ether);
    }

    function testFuzz_property(address recipient) public {
        vm.assume(address(recipient).code.length == 0);

        // Claim the first-withdrawal bonus: this pays out 100 wei to recipient.
        c.getFirstWithdrawalBonus(recipient);
        uint256 balanceAfterBonus = address(c).balance;

        // rewardsForA[recipient] is now zero, so a repeated withdraw must pay nothing.
        c.withdrawReward(recipient);
        uint256 balanceAfterRepeat = address(c).balance;

        assertTrue(balanceAfterRepeat == balanceAfterBonus);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(c));
        vm.assume(recipient != address(this));
        // The contract must hold Ether, otherwise the low-level call in
        // withdrawReward reverts for both versions and the rule is vacuous.
        vm.deal(address(c), 1 ether);

        // First-withdrawal-bonus flow: grants 100 wei and pays them out.
        c.getFirstWithdrawalBonus(recipient);
        uint balanceAfterBonus = address(c).balance;

        // Rule: once a recipient's rewards have been paid out, any further
        // withdrawReward(recipient) pays out nothing — the contract's balance
        // must be unchanged. The mutant never clears rewardsForA and pays 100
        // wei a second time, breaking the rule.
        c.withdrawReward(recipient);

        assertTrue(address(c).balance == balanceAfterBonus);
    }
}

