pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReentrantAttacker attacker;

    function setUp() public {
        c = new C();
        attacker = new ReentrantAttacker(c);
    }

    function testFuzz_property(uint256 funding) public {
        funding = bound(funding, 100, 1e30);
        vm.deal(address(this), funding);
        vm.prank(address(this));
        (bool sent, ) = address(c).call{value: funding}("");
        assertTrue(sent);

        bool ok;
        // attacker's receive() re-enters c.withdrawReward(attacker)
        try c.withdrawReward(address(attacker)) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a reentrant recipient can never successfully complete
        // the outer withdrawReward; the reentrant inner attempt must revert and
        // bubble up, so the whole call reverts.
        assertTrue(!ok);
    }
}

contract ReentrantAttacker {
    C c;
    bool reentered;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            c.withdrawReward(address(this));
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        // First call: succeeds on both versions.
        bool ok1;
        try c.withdrawReward(actor) { ok1 = true; } catch { ok1 = false; }

        // Second call: the lock must be released again, so it succeeds on P;
        // on M the lock stays set and it reverts.
        bool ok2;
        try c.withdrawReward(actor) { ok2 = true; } catch { ok2 = false; }

        assertTrue(ok1 && ok2, "withdrawReward must be reusable: lock is released after each call");
    }
}

