pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address a1, address a2) public {
        // keep the domain admissible: plain, externally-owned recipients distinct from c
        vm.assume(a1 != address(c) && a2 != address(c));
        vm.assume(a1.code.length == 0 && a2.code.length == 0);

        // fund c so the internal ETH payout call always succeeds (reference-legitimate failure mode)
        vm.deal(address(c), 1e30);

        bool ok1;
        bool ok2;
        try c.getFirstWithdrawalBonus(a1) { ok1 = true; } catch { ok1 = false; }
        try c.getFirstWithdrawalBonus(a2) { ok2 = true; } catch { ok2 = false; }

        assertTrue(ok1 && ok2, "withdrawReward must be reusable: the lock is released after each call");
    }
}
